import{z as A,x as E,o,c as p,q as i,j as n,D as e,d as t,s,S as d,b as l}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"注意力的反向传播","description":"","frontmatter":{"title":"注意力的反向传播","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/attention-backward.md","filePath":"llm/attention-backward.md","lastUpdated":1791413859000}'),m={name:"llm/attention-backward.md"};function B(D,a,h,f,_,c){const r=E("Mermaid");return o(),p("div",null,[a[2]||(a[2]=i('<h1 id="注意力的反向传播" tabindex="-1">注意力的反向传播 <a class="header-anchor" href="#注意力的反向传播" aria-label="Permalink to &quot;注意力的反向传播&quot;">​</a></h1><div class="epigraph"><p>缩放点积注意力把打分、归一化与加权收成三次矩阵运算；梯度必须沿同一条路返回，softmax 的 Jacobian 不能当成常数。</p><footer>—— 对照 Vaswani et al., Attention Is All You Need, NeurIPS 2017；反向重算见 Dao et al., FlashAttention, NeurIPS 2022</footer></div><p><a href="/llm/audio-visual-sync">上一课</a>把音画同步收在多模态生成课末。架构前向已经写完。本课是「训练基础与稳定性」第一课：训练要把标量损失送回查询、键、值与投影，注意力的 Jacobian 必须显式。<a href="/llm/sdpa">SDPA</a> 的前向、<a href="/llm/flashattention">FlashAttention</a> 的分块、<a href="/llm/causal-lm">因果语言模型</a> 的交叉熵，后课都不再从内容寻址讲起。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干把注意力写成</p> \\[S=\\frac{QK^\\top}{\\sqrt{d_k}},\\qquad A=\\mathrm{softmax}(S),\\qquad O=AV. \\]<p>推理只需要 \\(O\\)。训练还要 \\(\\partial\\mathcal{L}/\\partial Q\\)、\\(\\partial\\mathcal{L}/\\partial K\\)、\\(\\partial\\mathcal{L}/\\partial V\\)，再乘进 \\(W_Q,W_K,W_V\\)。缺口不是再推一遍点积方差，而是 <strong>softmax 把 \\(S\\) 变成行随机矩阵之后，上游的 \\(dO\\) 如何分配回每一对位置</strong>。若把 \\(A\\) 当常数，等于假装路由不随参数动，残差流上的注意力层几乎学不动。</p><p><a href="/llm/flashattention">FlashAttention</a> 故意不把 \\(A\\) 落在 HBM 上。反向若仍按朴素图去取 \\(A\\)，分块的意义就没了。于是出现第二条约束：数值上必须与物化算法同类，存储上却要能重算 \\(A\\)。本课先写物化形式的链式法则；重算只是同一 Jacobian 的实现。</p><p><span class="marginnote">Jacobian 可以理解成「一台输出对输入的敏感度表」：它逐项回答「输入坐标动一点点，输出坐标各动多少」。softmax 每一行的输出互相牵连（加起来必须是 1），所以它的敏感度表不是对角线，而要用 \\(\\mathrm{diag}(p)-pp^\\top\\) 这个公式整体描述——这正是梯度不能逐个坐标独立算的原因。</span></p><h3 id="softmax-行不是独立的坐标" tabindex="-1">softmax 行不是独立的坐标 <a class="header-anchor" href="#softmax-行不是独立的坐标" aria-label="Permalink to &quot;softmax 行不是独立的坐标&quot;">​</a></h3><p>对一行 \\(s\\)，令 \\(p=\\mathrm{softmax}(s)\\)，\\(g=\\partial\\mathcal{L}/\\partial p\\)。Jacobian 是 \\(\\mathrm{diag}(p)-pp^\\top\\)，于是</p> \\[\\frac{\\partial\\mathcal{L}}{\\partial s_i}=p_i\\Bigl(g_i-\\sum_j p_j g_j\\Bigr). \\]<p>贡献被行内均值减过。高权重位置若 \\(g\\) 接近行均值，落到 \\(s\\) 上的梯度接近 0——这就是饱和：分数已经 one-hot，<a href="/llm/attention-scale-stability">缩放</a> 当初要防的正是这一区。因果掩码在前向把无效位写成大负数，反向这些位的 \\(p\\) 已是 0，梯度也被掐掉。</p><p><span class="marginnote">不要把「注意力权重可视化」当成梯度解释。\\(A\\) 大只说明前向多读了这个值；\\(dS\\) 还取决于 \\(dO\\) 与 \\(V\\) 的相容性。值向量近零的高权重位置，对损失可以几乎无贡献。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记 \\(dO=\\partial\\mathcal{L}/\\partial O\\)。物化反向三步：</p> \\[dV=A^\\top dO,\\qquad dA=dO\\,V^\\top, \\]<p>再按上行公式把 \\(dA\\) 收成 \\(dS\\)，最后</p> \\[dQ=\\frac{dS\\,K}{\\sqrt{d_k}},\\qquad dK=\\frac{dS^\\top Q}{\\sqrt{d_k}}. \\]<p>缩放常数与前向同一条；漏掉它，等于把学习率沿头维悄悄乘了 \\(\\sqrt{d_k}\\)。多头是把头维拆开后各自做上述运算，再拼回 \\(d_{\\mathrm{model}}\\)。交叉注意力里 \\(Q\\) 与 \\(K,V\\) 来自不同序列，形状不同，链式法则不变。</p><p><span class="marginnote">漏掉 \\(\\sqrt{d_k}\\) 有多严重？代个数：\\(d_k=64\\) 时 \\(\\sqrt{d_k}=8\\)，反向少除一个 8，等于把 \\(W_Q,W_K\\) 的梯度悄悄放大 8 倍，SGD 下就是有效学习率放大 8 倍。表面上是训练「发散」或「某个头学崩了」，根因可能只是漏写了一个常数。</span></p><p>FlashAttention 的反向保存的是 \\(Q,K,V\\)、\\(O\\) 和行统计 \\((m,\\ell)\\)，不保存 \\(A\\)。需要 \\(A\\) 时按块重算 softmax，再在片上完成与 \\(dO\\) 的乘加。算术多了一次前向量级，HBM 少了一张 \\(n\\times n\\) 表。与层间梯度检查点不是同一粒度：这里重算的是核内部的权重，不是整层激活。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(dV=A^\\top dO\\) 是「按权重把输出梯度还原到值」。\\(dA=dO V^\\top\\) 是「输出梯度与值的点积，决定权重该增该减」。二者不对称：改 \\(V\\) 不经过 softmax Jacobian，改 \\(Q,K\\) 必须经过。所以值投影的梯度通常比查询、键更「直」，查询键则对饱和极其敏感。</p><p>残差把 \\(O\\) 加回流上，故 \\(dO\\) 含有后层直接回传的一项。Pre-LN 下这条公路不经过注意力内部，底层仍能收到梯度；但注意力<strong>内部</strong>的 \\(Q,K\\) 仍只通过 \\(dS\\) 学习。初始化若把点积放进饱和区，公路救的是主干，救不了注意力参数。这就是下一课要把自动微分图和初始化尺度接起来的原因：图保证链式法则不错，尺度保证 Jacobian 不先死。</p><p><span class="marginnote">可以把残差公路想象成高速公路，注意力内部是服务区的窄路：后层的梯度坐高速直达底层，所以主干再深也训得动；但「该看哪里」这件事（\\(Q,K\\)）只能在窄路上学。窄路一旦被饱和堵死（梯度接近 0），高速公路再通也帮不上忙。</span></p>',26)),(o(),n(d,null,{default:e(()=>[s(r,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%8D%9F%E5%A4%B1%E6%8A%8A%20dO%20%E9%80%81%E5%9B%9E%E8%BE%93%E5%87%BA%22%5D%20--%3E%20V%E8%B7%AF%5B%22%E7%BB%8F%20V%EF%BC%9AdV%20%3D%20A%20%E8%BD%AC%E7%BD%AE%E4%B9%98%20dO%22%5D%0A%20%20L%20--%3E%20A%E8%B7%AF%5B%22%E7%BB%8F%20A%EF%BC%9AdA%20%E5%86%8D%E8%BF%87%20softmax%20Jacobian%22%5D%0A%20%20V%E8%B7%AF%20--%3E%20WV%5B%22%E6%94%B9%E7%9A%84%E6%98%AF%20W_V%EF%BC%9A%E4%B8%8D%E7%A2%B0%20softmax%EF%BC%8C%E6%A2%AF%E5%BA%A6%E7%9B%B4%22%5D%0A%20%20A%E8%B7%AF%20--%3E%20SAT%5B%22dS%20%3D%20p%20%E4%B9%98%20(g%20%E5%87%8F%E8%A1%8C%E5%9D%87%E5%80%BC)%22%5D%0A%20%20SAT%20--%3E%7C%22%E8%A1%8C%E5%B7%B2%E6%8E%A5%E8%BF%91%20one-hot%EF%BC%9Ap%20%E5%87%A0%E4%B9%8E%E5%85%A8%200%22%7C%20DEAD%5B%22W_Q%E3%80%81W_K%20%E5%87%A0%E4%B9%8E%E6%94%B6%E4%B8%8D%E5%88%B0%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20SAT%20--%3E%7C%22p%20%E4%BB%8D%E6%9C%89%E5%88%86%E6%95%A3%E8%B4%A8%E9%87%8F%22%7C%20LIVE%5B%22W_Q%E3%80%81W_K%20%E6%AD%A3%E5%B8%B8%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"边界",tabindex:"-1"},[t("边界 "),l("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[4]||(a[4]=l("p",null,[t("本课不写 "),l("a",{href:"/llm/adamw"},"AdamW"),t(" 如何用这些梯度，也不写混合精度里 \\(QK^\\top\\) 的溢出——那是主干已有的数值课与后课稳定性。手写 Jacobian 只为钉住对象：\\(dQ,dK,dV\\) 与 \\(A\\) 的关系。实现几乎总是框架反传或融合核，但融合核必须与上述公式同类，否则「精确注意力」的声称不成立。")],-1)),a[5]||(a[5]=l("p",null,"线性注意力、核函数注意力改的是前向定义，Jacobian 另写，不能复用 softmax 这一行。GQA / MQA 只是键值在头维共享，链式法则多一次对共享维的求和，不改 softmax 本身。",-1)),(o(),n(d,null,{default:e(()=>[s(r,{id:"mermaid-78",class:"mermaid",graph:"flowchart%20TD%0A%20%20DO%5B%22%E4%B8%8A%E6%B8%B8%20dO%22%5D%20--%3E%20DV%5B%22dV%20%3D%20A%20%E8%BD%AC%E7%BD%AE%E4%B9%98%20dO%22%5D%0A%20%20DO%20--%3E%20DA%5B%22dA%20%3D%20dO%20%E4%B9%98%20V%20%E8%BD%AC%E7%BD%AE%22%5D%0A%20%20DA%20--%3E%20DS%5B%22softmax%20Jacobian%20%E5%BE%97%20dS%22%5D%0A%20%20DS%20--%3E%20DQ%5B%22dQ%20%E7%BB%8F%E7%BC%A9%E6%94%BE%22%5D%0A%20%20DS%20--%3E%20DK%5B%22dK%20%E7%BB%8F%E7%BC%A9%E6%94%BE%22%5D%0A%20%20A%5B%22%E5%89%8D%E5%90%91%E6%9D%83%E9%87%8D%20A%22%5D%20--%3E%20DV%0A%20%20A%20--%3E%20DS%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>注意力反向沿 \\(O\\leftarrow A\\leftarrow S\\leftarrow Q,K\\) 与 \\(O\\leftarrow V\\) 两条路走；后者不经过 softmax Jacobian。</li><li>行内 \\(dS_i=p_i(g_i-\\sum p_j g_j)\\)：饱和时查询键几乎收不到梯度。</li><li>FlashAttention 用重算代替存 \\(A\\)，数学对象仍是同一 Jacobian。</li><li>残差公路不替代注意力内部的尺度；初始化把点积送进饱和区，公路也救不了 \\(W_Q,W_K\\)。</li><li>后课默认会这条链式法则，不再从 SDPA 前向重推。</li><li>出处：Vaswani et al., <em>Attention Is All You Need</em>, NeurIPS 2017；Dao et al., <em>FlashAttention</em>, NeurIPS 2022。</li></ul>',2))])}const b=A(m,[["render",B]]);export{S as __pageData,b as default};
